using AutoMapper; using MediatR; using SMIS.Application.Common.Response; using SMIS.Application.DTO.ProductPrices; using SMIS.Application.Identity.IServices; using SMIS.Application.Repositories.ProductPrices; using SMIS.Domain.Services;
namespace SMIS.Application.Features.ProductPrices.Queries;
public record ProductPricePullQuery(DateTime ChangedSince) : IRequest<Result<List<ProductPriceDto>>>;
internal sealed class ProductPricePullQueryHandler : IRequestHandler<ProductPricePullQuery,Result<List<ProductPriceDto>>>{private readonly IProductPriceRepository _repository;private readonly ICurrentUser _user;private readonly IMapper _mapper;public ProductPricePullQueryHandler(IProductPriceRepository repository,ICurrentUser user,IMapper mapper)=>(_repository,_user,_mapper)=(repository,user,mapper);public async Task<Result<List<ProductPriceDto>>> Handle(ProductPricePullQuery r,CancellationToken ct){var since=DateTimeService.NormalizeUtc(r.ChangedSince);var shopId=_user.GetShopId();var admin=_user.IsSuperAdmin();var items=await _repository.GetAllAsync(p=>p.LastModifiedUtc>since&&(admin||p.Product.ShopId==shopId),includeProperties:"Product",ignoreQueryFilters:true);return Result<List<ProductPriceDto>>.SuccessResult(_mapper.Map<List<ProductPriceDto>>(items));}}
